function referencePage(){const term=search.toLowerCase();const rows=reference.filter(r=>(filter==='All'||r[0]===filter)&&(!term||r.slice(0,6).join(' ').toLowerCase().includes(term)));return `<p class="eyebrow">Look something up</p><h1 class="page-title">Reference</h1><p class="lead">Short reminders for the concepts you meet in lessons.</p><div class="row"><label class="field-label" for="reference-query">Search reference</label><input id="reference-query" class="field" style="max-width:380px" value="${esc(search)}" placeholder="Try paragraph, flexbox, or click"></div><div class="filterbar">${['All','HTML','CSS','JavaScript'].map(f=>`<button data-filter="${f}" class="${filter===f?'active':''}" aria-pressed="${filter===f}">${f}</button>`).join('')}<button data-action="clear-filters">Clear filters</button></div>${rows.length?`<div class="grid grid-2">${rows.map(r=>`<article class="card"><span class="pill ${r[0]==='JavaScript'?'js':r[0].toLowerCase()}">${r[0]}</span><h2 style="margin:14px 0 8px">${esc(r[1])}</h2><p>${esc(r[3])}</p><pre class="code-block">${esc(r[4])}</pre><p class="small muted">Common mistake: ${esc(r[5])}</p><a href="#/lesson/lesson-${String(r[6]).padStart(2,'0')}">Related lesson ${r[6]}</a></article>`).join('')}</div>`:'<div class="notice">No reference entries match. Try another word or clear the filters.</div>'}${footer()}`}
function searchPage(){const q=search.trim().toLowerCase();const matches=(xs,fields)=>xs.filter(x=>fields(x).toLowerCase().includes(q));const l=q?matches(lessons,x=>x.title+' '+x.explanation):[],p=q?matches(projects,x=>x.title+' '+x.brief):[],r=q?matches(reference,x=>x.join(' ')):[];return `<h1 class="page-title">Search</h1><p class="lead">${q?'Results for “'+esc(search)+'”':'Enter a term in the search bar to find lessons, projects, and reference entries.'}</p>${q&&!l.length&&!p.length&&!r.length?'<div class="notice">No results. Try a broader term.</div>':''}${[['Lessons',l,x=>`<a href="#/lesson/${x.id}">${x.title}</a>`],['Projects',p,x=>`<a href="#/project/${x.id}">${x.title}</a>`],['Reference',r,x=>`<a href="#/reference">${x[1]}</a>`]].map(([n,items,link])=>items.length?`<section class="card" style="margin-top:16px"><h2>${n}</h2><ul>${items.map(x=>`<li>${link(x)}</li>`).join('')}</ul></section>`:'').join('')}${footer()}`}
