function drawLines(){const input=$('#code-editor'),lines=$('#line-numbers');if(!input||!lines)return;lines.textContent=Array.from({length:Math.max(1,input.value.split('\n').length)},(_,i)=>i+1).join('\n');lines.scrollTop=input.scrollTop}
function storeEditor(){const input=$('#code-editor');if(!input)return;const key=draftKey();state.drafts[key]={...files(),[lang]:input.value};queueSave();if(checkResult){checkResult={...checkResult,outdated:true};drawChecks()}}
