function drawChecks(){const area=$('#check-area');if(!area||!checkResult)return;area.innerHTML=`<div class="notice ${checkResult.outdated?'':' '+(checkResult.all?'success':'error')}"><strong>${checkResult.outdated?'Results out of date — run Check My Work again':checkResult.all?'All listed checks passed':'Keep working on these checks'}</strong><ul class="check-list">${checkResult.items.map(x=>`<li class="${x.pass?'pass':'fail'}">${x.pass?'✓':'✕'} ${esc(x.label)}</li>`).join('')}</ul>${checkResult.kind==='general'?'<p class="small">These are basic run checks, not a full evaluation of the lesson goal. Review the stated task yourself.</p>':''}</div>`}
function runHomeExample(){const frame=$('#home-preview');if(frame)frame.srcdoc='<!doctype html><meta charset="utf-8"><body style="font:16px system-ui;padding:16px">'+$('#home-code').value+'</body>'}
function runWorkspace(check=false,override=null){const frame=$('#preview');if(!frame)return;storeEditor();const item=currentItem(),kind=check&&item?.id?.startsWith('lesson')?item.id+'-'+mode:check&&item?.id?.startsWith('project')?item.id:check?'general':'';$('#console-output').textContent='';if(runCleanup)runCleanup();checkResult=check?{items:[],all:false,outdated:false,kind:kind==='general'?'general':'specific'}:null;if(check)drawChecks();else $('#check-area').innerHTML='';const source=override||files();runCleanup=execute(frame,source,{checkKind:kind,onMessage:(type,payload)=>{if(type==='console'){$('#console-output').textContent+=payload.level+': '+payload.text+'\n'}if(type==='error'){const line=payload.name+': '+payload.message;$('#console-output').textContent+=line+'\n';$('#console-details').open=true;if(check){checkResult={items:[{label:line,pass:false}],all:false,outdated:false,kind:'error'};drawChecks()}}if(type==='checks'&&check){checkResult={items:payload,all:payload.every(x=>x.pass),outdated:false,kind:kind==='general'?'general':'specific'};drawChecks();if(item?.id?.startsWith('lesson')&&kind!=='general'&&checkResult.all){state.progress[item.id][mode+'Passed']=true;queueSave()}if(item?.id?.startsWith('project')&&checkResult.all){const data=state.projectData[item.id]||(state.projectData[item.id]={checks:{},selfReview:{}});data.objectivePassed=true;queueSave()}}},onTimeout:()=>{checkResult={items:[{label:'Code took too long. Check loops and try again.',pass:false}],all:false,outdated:false,kind:'error'};drawChecks();$('#console-output').textContent='Preview stopped after a timeout.'}});if(item?.id?.startsWith('lesson')&&check){state.progress[item.id].attempts=(state.progress[item.id].attempts||0)+1;queueSave()}}
function confirmAction(title,message,accept='Confirm'){return new Promise(resolve=>{const el=document.createElement('div');el.className='modal-backdrop';el.innerHTML=`<div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><h2 id="modal-title">${esc(title)}</h2><p>${esc(message)}</p><div class="actions"><button class="button secondary" data-result="cancel">Cancel</button><button class="button danger" data-result="ok">${esc(accept)}</button></div></div>`;document.body.append(el);const prior=document.activeElement;el.querySelector('[data-result="cancel"]').focus();const finish=v=>{el.remove();prior?.focus();resolve(v)};el.addEventListener('click',e=>{if(e.target.dataset.result)finish(e.target.dataset.result==='ok')});el.addEventListener('keydown',e=>{if(e.key==='Escape')finish(false);if(e.key==='Tab'){const buttons=[...el.querySelectorAll('button')],i=buttons.indexOf(document.activeElement);if(e.shiftKey&&i===0){e.preventDefault();buttons.at(-1).focus()}else if(!e.shiftKey&&i===buttons.length-1){e.preventDefault();buttons[0].focus()}}})})}
function lessonComplete(){const l=currentItem();if(!l?.id.startsWith('lesson'))return;const record=state.progress[l.id],quizDone=l.quiz.every((_,i)=>record.quizCorrect?.[i]);if(!quizDone){toast('Answer all knowledge-check questions first.');return}if(needsObjectiveCheck(l)&&(!record.guidedPassed||!record.challengePassed)){toast('Pass both guided and challenge checks first.');return}if(!needsObjectiveCheck(l)&&!record.selfReviewed){toast('Review both exercises and confirm your work first.');return}record.status='Completed';record.completedAt=new Date().toISOString();queueSave();toast('Lesson complete. Your progress was saved on this device.');render()}
function projectComplete(){const p=currentItem();if(!p?.id.startsWith('project'))return;const d=state.projectData[p.id]||{};if(!d.objectivePassed){toast('Pass the objective checks first.');return}if(!p.requirements.every((_,i)=>d.checks?.[i])||![0,1,2].every(i=>d.selfReview?.[i])){toast('Finish the feature checklist and self-review before completing.');return}state.progress[p.id]={...state.progress[p.id],status:'Completed',completedAt:new Date().toISOString()};queueSave();toast('Project complete.');render()}
app.addEventListener('change',e=>{const t=e.target;if(!(t instanceof HTMLInputElement)||t.type!=='radio'||!/^q-\d+$/.test(t.name))return;const i=Number(t.name.slice(2));quizAnswers[i]=Number(t.value);if(quizFeedback[i]&&quizFeedback[i].answer!==quizAnswers[i]){delete quizFeedback[i];const target=$('#quiz-feedback-'+i);if(target){target.textContent='';target.classList.remove('is-correct','is-incorrect')}}});
function quizCheck(){const l=currentItem();if(!l?.quiz)return;const record=state.progress[l.id];record.quizCorrect=record.quizCorrect||{};l.quiz.forEach((q,i)=>{const chosen=$(`input[name="q-${i}"]:checked`),target=$('#quiz-feedback-'+i);if(!chosen){quizFeedback[i]={answer:null,correct:false,text:'Choose an answer.'};target.textContent=quizFeedback[i].text;target.classList.remove('is-correct');target.classList.add('is-incorrect');return}const answer=Number(chosen.value),right=answer===q.answer,text=(right?'Correct. ':'Not yet. ')+q.explanation;quizFeedback[i]={answer,correct:right,text};if(right)record.quizCorrect[i]=true;target.textContent=text;target.classList.toggle('is-correct',right);target.classList.toggle('is-incorrect',!right);if(right)document.querySelectorAll(`input[name="q-${i}"]`).forEach(input=>input.disabled=true)});queueSave();announce('Knowledge-check feedback updated.')}
function showSolution(item,kind='lesson'){const area=$('#solution-area');if(!area)return;const solution=kind==='project'?item.solution:mode==='challenge'?(item.challengeSolution||item.solution):item.solution;area.innerHTML=`<p>${esc(solution.explanation)}</p><pre class="code-block">${esc(solution.html)}${solution.css?'\n\n/* CSS */\n'+esc(solution.css):''}${solution.js?'\n\n// JavaScript\n'+esc(solution.js):''}</pre><button class="button secondary" data-action="load-solution">Load into editor</button>`;area.classList.remove('hidden');solutionVisible=true;if(kind==='lesson'){state.progress[item.id].solutionViewed=true;queueSave()}}
