async function importBackup(file){let backup;try{backup=parseBackup(await file.text())}catch(e){toast('Import failed: '+e.message);return}const completedCount=Object.values(backup.progress).filter(r=>r?.status==='Completed').length,draftCount=Object.keys(backup.drafts).length;if(!await confirmAction('Import WebSteps backup?',`This backup contains ${completedCount} completed items and ${draftCount} drafts. It will replace your current local learning data. Export your current data first if you want a copy.`,'Import and replace'))return;const old=state;try{state=backup;await saveState(state,accountUser?'account-'+accountUser.id:'state');if(accountUser)queueSave();saveStatus='Saved on this device';render();toast('Backup imported.')}catch(e){state=old;toast('Import failed: '+e.message)}}
