function enhanceLesson(){const l=currentItem();if(!l?.id?.startsWith('lesson'))return;const record=state.progress[l.id]||{};if(!needsObjectiveCheck(l)){const complete=$('[data-action="complete-lesson"]');complete?.insertAdjacentHTML('beforebegin',`<label class="notice" style="display:block;margin:0 0 14px"><input type="checkbox" id="lesson-self-review" ${record.selfReviewed?'checked':''}> I completed both exercises and reviewed my result against the lesson goal.</label>`)}for(const [i,correct] of Object.entries(record.quizCorrect||{})){if(correct){const q=l.quiz[Number(i)],input=document.querySelector(`input[name="q-${i}"][value="${q.answer}"]`);if(input)input.checked=true;document.querySelectorAll(`input[name="q-${i}"]`).forEach(x=>x.disabled=true);const feedback=$('#quiz-feedback-'+i);if(feedback)feedback.textContent='Correct. '+q.explanation}}}
function highlightCode(source){const re=/(<!--[^]*?-->|\/\*[^]*?\*\/|\/\/[^\n]*|<\/?[A-Za-z][^>]*>|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|`(?:\\.|[^`\\])*`|\b(?:const|let|function|return|if|else|for|while|await|async|new|true|false|null|undefined)\b|\b\d+(?:\.\d+)?\b)/g;let html='',last=0,match;while((match=re.exec(source))){html+=esc(source.slice(last,match.index));const token=match[0],type=token.startsWith('<!--')||token.startsWith('/*')||token.startsWith('//')?'comment':token.startsWith('<')?'tag':/^["'`]/.test(token)?'string':/^\d/.test(token)?'number':'keyword';html+=`<span class="token-${type}">${esc(token)}</span>`;last=re.lastIndex}return html+esc(source.slice(last))+'\n'}
