app.addEventListener('change',e=>{if(e.target.id==='lesson-self-review'){const l=currentItem();if(l?.id?.startsWith('lesson')){state.progress[l.id].selfReviewed=e.target.checked;queueSave()}}});
function mergeLearning(local,remote){const out=structuredClone(remote);out.progress={...local.progress,...remote.progress};for(const [id,record] of Object.entries(local.progress)){const existing=out.progress[id];if(record?.status==='Completed'&&existing?.status!=='Completed')out.progress[id]=record}out.drafts={...remote.drafts};const found=[];for(const [key,draft] of Object.entries(local.drafts)){if(out.drafts[key]&&JSON.stringify(out.drafts[key])!==JSON.stringify(draft)){const copyKey=key+'-local-'+Date.now();out.drafts[copyKey]=draft;found.push({key,copyKey,localTime:local.updatedAt,cloudTime:remote.updatedAt})}else out.drafts[key]=draft}out.projectData={...local.projectData,...remote.projectData};out.resume=remote.resume||local.resume;return {state:out,conflicts:found}}
async function enterAccount(user,transfer=false){accountUser=user;const key='account-'+user.id;let local=await loadState(key),cloud=null;try{cloud=(await accountService.readCloud())?.payload||null}catch(e){cloudError=e.message}if(cloud&&!('schemaVersion'in cloud))cloud=null;let combined=cloud||local;if(local.updatedAt&&cloud){const merged=mergeLearning(local,cloud);combined=merged.state;conflicts=merged.conflicts}if(transfer){const guest=await loadState();const merged=mergeLearning(guest,combined);combined=merged.state;conflicts.push(...merged.conflicts)}state=combined;await saveState(state,key);if(!conflicts.length){try{await accountService.writeCloud(state);saveStatus='Saved to your account';cloudError=''}catch(e){cloudError=e.message;saveStatus='Sync failed — Retry'}}else saveStatus='Review draft conflicts before syncing';storageReady=true;render()}
queueSave=function(){if(!storageReady)return;saveStatus='Saving…';updateSave();clearTimeout(saveTimer);saveTimer=setTimeout(async()=>{try{await saveState(state,accountUser?'account-'+accountUser.id:'state');saveStatus=navigator.onLine?'Saved on this device':'Offline — changes saved on this device';updateSave();if(accountUser&&!conflicts.length&&navigator.onLine){saveStatus='Syncing…';updateSave();try{await accountService.writeCloud(state);saveStatus='Saved to your account';cloudError=''}catch(e){cloudError=e.message;saveStatus='Sync failed — Retry'}updateSave()}}catch(e){saveStatus='Save failed — Retry';updateSave();announce('Could not save: '+e.message)}},450)};
accountPage=function(){if(!accountService.accountConfigured())return `<p class="eyebrow">Optional account</p><h1 class="page-title">Account</h1><div class="notice">Account registration and syncing need a dedicated WebSteps account service. Guest learning is available now; progress saves on this device.</div><p><a class="button" href="#/dashboard">Continue as Guest</a></p>${footer()}`;if(accountUser)return `<p class="eyebrow">Your account</p><h1 class="page-title">Account</h1><p class="lead">Signed in as ${esc(accountUser.email||'learner')}</p><div class="stack"><div class="card"><h2>Sync status</h2><p data-save-status>${saveStatus}</p>${cloudError?`<div class="notice error">${esc(cloudError)}</div><button class="button secondary" data-account-action="retry-sync">Retry sync</button>`:''}${conflicts.length?`<div class="notice"><strong>Draft conflicts need review</strong><p>Both versions are preserved. Choose a version for each original draft, or keep both copies.</p>${conflicts.map((c,i)=>`<div class="card" style="margin:10px 0"><strong>${esc(c.key)}</strong><p class="small muted">Local: ${esc(c.localTime||'unknown time')} · Account: ${esc(c.cloudTime||'unknown time')}</p><details><summary>Preview versions</summary><pre class="code-block">Local: ${esc(JSON.stringify(state.drafts[c.copyKey]).slice(0,600))}\nAccount: ${esc(JSON.stringify(state.drafts[c.key]).slice(0,600))}</pre></details><select class="field" data-conflict="${i}"><option value="both">Keep both</option><option value="local">Use local for main draft</option><option value="cloud">Use account for main draft</option></select></div>`).join('')}<button class="button" data-account-action="resolve-conflicts">Apply draft choices</button></div>`:''}</div><div class="card"><h2>Change password</h2><form id="password-form"><label class="field-label">New password<input class="field" type="password" name="password" minlength="8" required></label><button class="button" style="margin-top:12px">Change password</button></form></div><div class="card"><h2>Account actions</h2><div class="row"><button class="button secondary" data-account-action="logout">Log out</button><button class="button danger" data-account-action="delete">Delete account</button></div><p class="small muted">Deleting the account removes cloud progress. Export a backup first if you want a copy.</p></div></div>${footer()}`;return `<p class="eyebrow">Optional account</p><h1 class="page-title">${accountMode==='register'?'Create account':accountMode==='recover'?'Reset password':'Sign in'}</h1><p class="lead">An account syncs progress and drafts across devices. You can always continue as a guest.</p><div class="grid grid-2"><div class="card"><div class="filterbar"><button data-account-mode="login" class="${accountMode==='login'?'active':''}">Sign in</button><button data-account-mode="register" class="${accountMode==='register'?'active':''}">Create account</button></div><form id="auth-form"><label class="field-label">Email<input class="field" type="email" name="email" autocomplete="email" required></label>${accountMode!=='recover'?'<label class="field-label" style="margin-top:14px">Password<input class="field" type="password" name="password" autocomplete="current-password" minlength="8" required></label><label class="small" style="display:block;margin:8px 0"><input type="checkbox" id="show-password"> Show password</label>':''}<button class="button" style="margin-top:12px" ${accountBusy?'disabled':''}>${accountBusy?'Working…':accountMode==='register'?'Create account':accountMode==='recover'?'Send reset email':'Sign in'}</button></form><div class="row" style="margin-top:12px">${accountMode==='login'?'<button class="button ghost" data-account-mode="recover">Forgot password?</button>':''}<button class="button ghost" data-account-action="resend">Resend verification email</button></div><p id="account-feedback" aria-live="polite"></p></div><div class="card"><h2>Continue as Guest</h2><p>Your existing guest work stays on this device. Creating an account can transfer it after verification.</p><a class="button secondary" href="#/dashboard">Continue as Guest</a></div></div>${footer()}`};
app.addEventListener('change',e=>{if(e.target.id==='show-password'){const input=$('#auth-form [name=password]');if(input)input.type=e.target.checked?'text':'password'}});
app.addEventListener('submit',async e=>{if(!['auth-form','password-form'].includes(e.target.id))return;e.preventDefault();const form=e.target,values=new FormData(form),button=form.querySelector('button[type=submit],button:not([type])'),feedback=form.querySelector('#account-feedback');accountBusy=true;if(button){button.disabled=true;button.textContent=form.id==='auth-form'&&accountMode==='register'?'Sending verification email…':'Working…'}if(form.id==='auth-form'&&accountMode==='register'&&feedback){feedback.className='notice';feedback.setAttribute('role','status');feedback.textContent='Sending verification email…'}try{if(form.id==='password-form'){await accountService.updatePassword(values.get('password'));toast('Password changed.')}else if(accountMode==='register'){await accountService.signUp(String(values.get('email')),String(values.get('password')));localStorage.setItem('websteps-pending-transfer','1');if(feedback){feedback.className='notice success';feedback.setAttribute('role','status');feedback.textContent='✓ Verification email sent. Check your inbox and spam folder. Your guest work stays on this device until the account is confirmed.'}}else if(accountMode==='recover'){await accountService.sendReset(String(values.get('email')));if(feedback){feedback.className='notice success';feedback.setAttribute('role','status');feedback.textContent='If that email has an account, a password-reset email is on its way. Check your inbox and spam folder.'}}else{const data=await accountService.signIn(String(values.get('email')),String(values.get('password')));await enterAccount(data.user,false);toast('Signed in.')}}catch(error){if(feedback){feedback.className='notice error';feedback.setAttribute('role','alert');feedback.textContent=error.message}else toast(error.message)}finally{accountBusy=false;if(button){button.removeAttribute('disabled');button.textContent=form.id==='password-form'?'Change password':accountMode==='register'?'Create account':accountMode==='recover'?'Send reset email':'Sign in'}}});
app.addEventListener('click',async e=>{const modeButton=e.target.closest('[data-account-mode]');if(modeButton){accountMode=modeButton.dataset.accountMode;render();return}const button=e.target.closest('[data-account-action]');if(!button)return;try{switch(button.dataset.accountAction){case'resend':{const email=$('#auth-form [name=email]')?.value;if(!email){toast('Enter your email first.');return}await accountService.resendVerification(email);toast('If that email needs verification, another link is on its way.');break}case'logout':await accountService.signOut();accountUser=null;conflicts=[];state=await loadState();saveStatus='Saved on this device';location.hash='#/dashboard';render();break;case'retry-sync':await accountService.writeCloud(state);saveStatus='Saved to your account';cloudError='';render();break;case'resolve-conflicts':for(const [i,c] of conflicts.entries()){const choice=document.querySelector(`[data-conflict="${i}"]`)?.value;if(choice==='local')state.drafts[c.key]=state.drafts[c.copyKey];if(choice==='cloud')delete state.drafts[c.copyKey]}conflicts=[];queueSave();render();break;case'delete':if(!await confirmAction('Delete your WebSteps account?','Cloud progress and the account will be permanently removed. Your guest copy remains on this device. Export your account data first if needed.','Delete account'))return;await accountService.deleteAccount();accountUser=null;state=await loadState();location.hash='#/dashboard';render();toast('Account deleted.');break}}catch(error){cloudError=error.message;toast(error.message)}});
const accountPageBeforeAuthNotice=accountPage;
accountPage=function(){return accountPageBeforeAuthNotice().replace('An account syncs progress and drafts across devices. You can always continue as a guest.','Production sign-in redirects are configured. Existing accounts can sign in now; public sign-up verification and password-reset email need production SMTP. You can always continue as a guest.');};
const lessonPageBeforeQuizFeedback=lessonPage;
lessonPage=function(l){return lessonPageBeforeQuizFeedback(l).replace(/<p id="quiz-feedback-(\d+)" class="small" aria-live="polite"><\/p>/g,(_,index)=>{const i=Number(index),feedback=quizFeedback[i],visible=feedback&&(feedback.answer===null||feedback.answer===quizAnswers[i]);return `<p id="quiz-feedback-${i}" class="small quiz-feedback ${visible?(feedback.correct?'is-correct':'is-incorrect'):''}" aria-live="polite">${visible?esc(feedback.text):''}</p>`})};
const baseRender=render;
function needsObjectiveCheck(lesson){return lesson.order>=4&&lesson.order<=42||lesson.order===45||lesson.order===47}
render=function(){baseRender();const l=currentItem(),hintArea=$('#hint-area');if(hintIndex>=0&&l?.hints&&hintArea){const shown=Math.min(hintIndex,l.hints.length-1);hintArea.textContent=l.hints[shown];hintArea.classList.remove('hidden');const hintButton=$('[data-action="hint"]');if(hintButton){hintButton.dataset.hint=String(Math.min(shown+1,l.hints.length-1));hintButton.textContent=shown>=l.hints.length-2?'Show final hint':'Show next hint'}}const solutionArea=$('#solution-area');if(solutionVisible&&solutionMarkup&&solutionArea)solutionArea.innerHTML=solutionMarkup;const t=$('#theme-setting'),m=$('#motion-setting'),s=$('#size-setting');if(t)t.value=preferences.theme;if(m)m.value=preferences.motion;if(s)s.value=String(preferences.editorSize);const side=$('#sidebar');if(side){const close=document.createElement('button');close.className='mobile-only icon-button';close.textContent='Close navigation';close.setAttribute('aria-label','Close navigation');close.addEventListener('click',()=>side.classList.remove('open'));side.prepend(close)}};
window.addEventListener('hashchange',()=>{runCleanup?.();runCleanup=null;mode='guided';lang='html';mobile='learn';checkResult=null;quizAnswers={};quizFeedback={};hintIndex=-1;solutionVisible=false;solutionMarkup='';window.scrollTo(0,0);render()});
(async()=>{try{state=await loadState();storageReady=true;saveStatus=navigator.onLine?'Saved on this device':'Offline — changes saved on this device';const user=await accountService.restoreSession();if(user){await enterAccount(user,localStorage.getItem('websteps-pending-transfer')==='1');localStorage.removeItem('websteps-pending-transfer')}}catch(e){saveStatus='Saving unavailable or account session expired';toast(e.message)}render();const theme=$('#theme-setting');if(theme)theme.value=preferences.theme;const motion=$('#motion-setting');if(motion)motion.value=preferences.motion;const size=$('#size-setting');if(size)size.value=preferences.editorSize})();
if(document.modelContext?.registerTool){
  const tool={name:'get_learning_progress',title:'Get learning progress',description:'Read completed WebSteps lessons and projects.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({completed:countCompleted(),required:52,nextLessonId:nextLesson().id})};
  const open={name:'open_lesson',title:'Open lesson',description:'Navigate to a WebSteps lesson by stable ID.',inputSchema:{type:'object',properties:{lessonId:{type:'string'}},required:['lessonId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({lessonId})=>{if(!lessons.some(l=>l.id===lessonId))throw Error('Unknown lesson ID');location.hash='#/lesson/'+lessonId;return {opened:lessonId}}};
  Promise.resolve(document.modelContext.registerTool(tool)).then(()=>document.modelContext.registerTool(open)).catch(()=>{});
}
